package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Typed exact-original SMR/HEIDI execution, with complete native family/ratio checks and atomic admission. */
public final class SmrWorkflowCli {
    private SmrWorkflowCli() { }
    static final String SCOPE="Original SMR1.3.1/1.4.3 single/multi-SNP analysis and original/new/off HEIDI. Native Java checks literal GWAS/QTL/BESD/reference axes, binary32 quantization, exact-or-swapped alleles, source MAF/frequency exclusions, null-SNP correlation, complete cis/top-SNP/probe families, rounded single-instrument effects/SE/P and multi-SNP auxiliary identities. LD pruning, HEIDI mixtures/tails and multi-SNP fitting remain upstream and are not independently refitted. Source top selection retains its1e-6 near-tie convention; multi-SNP set-wind can extend the cis window. Labels for assembly, population and units are caller assertions, not validation, liftover, causal proof or historical paper-binary reproduction. Logical capacities do not impose RAM/disk quotas. This development entry point installs nothing; exact permitted source/program/ELF closure is required.";
    static final String ACTION="Require exit0 AND analysis-status.json result_admitted=true. Read WARNINGS.md, provenance.json, every native ledger, native-audit.json, process-receipt.json and original stdout/stderr. SKIP3: dependent analysis was skipped; supply the exact permitted Linux x86_64 source/runtime profile or skip that analysis. FAIL2: no result from this atomic batch is admitted, including earlier successful cases. Preserve original inputs/logs/unadmitted worker files; correct the named data/source/permission/capacity/timeout cause and retry a NEW output path. Never silently repair identifiers/alleles, drop probes/variants, replace NA/NaN/Inf, infer ancestry/assembly/units or interpret unavailable/nonrejected HEIDI as proof of shared causality. P150's reported1.03 is not automatically1.3.1.";
    private record Captured(Path original,Path copy,NextflowFiles.Pin pin){void verify()throws IOException{require(pin.equals(NextflowFiles.pin(original,pin.bytes(),()->{}))&&pin.equals(NextflowFiles.pin(copy,pin.bytes(),()->{})),"Original/captured input changed: "+original);}}
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(output,"java -cp DEVELOPMENT.jar org.jlinalg.cli.SmrWorkflowCli --request request.json\nClosed schema_version1/mode ANALYZE. Declare exact profile/version; gwas; qtl qfile or BESD prefix with source-binary32 precision; none or PLINK-BED LD reference with assembly/population/coordinate/missing-call policies; all/supplied probes; units; source/runtime; NEW out;1..16 typed single/multi cases and explicit HEIDI/frequency/overlap settings. No arbitrary options/scripts or model fallback. See SmrWorkflowRequest and the workflow guide.\n"+SCOPE+"\n"+ACTION);return 0;}
            require(args.length==2&&args[0].equals("--request"),"Require --request UTF8_JSON or --help");Path request=Path.of(args[1]).toAbsolutePath().normalize();var requestPin=NextflowFiles.pin(request,1048576,()->{});byte[] raw=NextflowFiles.bytes(request,1048576);require(raw.length==requestPin.bytes()&&NextflowFiles.sha(raw).equals(requestPin.sha256()),"Request changed during intake");var r=SmrWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),1048576,100000)),request.getParent());var protectedPaths=new ArrayList<Path>(r.inputs().values());protectedPaths.addAll(List.of(request,r.source(),r.runtime()));Path out=resolved(r.out());for(Path p:protectedPaths){Path path=resolved(p);require(!out.startsWith(path)&&!path.startsWith(out),"Output overlaps an input, request, original source or runtime, including aliases");}int[] exit={0};
            transaction(r.out(),(stage,manifest)->{
                var warnings=new ArrayList<String>();warnings.add(SCOPE);warnings.add("BIOLOGICAL INPUT REVIEW: confirm every supplied assembly, allele coding, effect unit, QTL definition and LD population. Mean imputation is confined to original derived LD; captured calls are not changed. Missing frequency remains unknown; the source skips some frequency comparisons when zero/unknown. Source GWAS p=NA is printed as0 by original atof; the raw token is retained and this is not a native P estimate.");if(r.version().equals("1.3.1")&&r.reference().get("kind").equals("none"))warnings.add("ORIGINAL1.3.1 NO-REFERENCE FAILURE: its literal no-reference HEIDI-off path closes a null LD file. A nonzero original exit admits no result. Supply a declared BED reference to select the original BED dispatch, or use an explicitly different declared supported source profile; no dummy reference or source patch is substituted. Single-SNP HEIDI-off still applies no BED/MAF filter.");var state=new LinkedHashMap<String,Object>();state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("result_admitted",false);
                if(r.qtl().get("kind").equals("qfile")&&r.version().equals("1.3.1"))warnings.add("ORIGINAL1.3.1 QFILE PREPARATION: for nonmissing P in[1e-150,1), the original derives SE from beta and P even when SE is supplied. P0 is adjusted to the minimum normal double and then keeps supplied SE; P1 and more extreme P keep supplied SE. Inspect native-quantization-ledger.tsv for every raw SE/P, expected stored binary32 SE and changed-SE flag. Java audits that source behavior and never rewrites the supplied file. Original1.4.3 uses the supplied SE instead.");
                try{
                    verify(request,requestPin);Files.write(stage.resolve("source-request.json"),raw,StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(stage.resolve("effective-request.json"),r.effective());Path inputs=Files.createDirectory(stage.resolve("inputs"));var captures=new ArrayList<Captured>();long remaining=r.inputBytes();for(var e:r.inputs().entrySet()){Captured c=capture(e.getValue(),inputs.resolve(e.getKey()),remaining);remaining-=c.pin().bytes();captures.add(c);}var pins=new LinkedHashMap<String,Object>();for(Captured c:captures)pins.put(c.copy().getFileName().toString(),Map.of("bytes",c.pin().bytes(),"sha256",c.pin().sha256()));manifest.put("captured_inputs",pins);var budget=new SmrWorkflowInputs.Budget(r.nativeOperations());var gwas=SmrWorkflowInputs.gwas(inputs.resolve("gwas.ma"),r,budget);SmrWorkflowInputs.Qtl supplied=r.qtl().get("kind").equals("qfile")?SmrWorkflowInputs.qfile(inputs.resolve("qtl.qfile"),stage.resolve("native-quantization-ledger.tsv"),r,budget):SmrWorkflowBesd.read(inputs.resolve("qtl"),r,budget);
                    Path worker=Files.createDirectory(stage.resolve("worker"));var runtime=SmrWorkflowRuntime.prepare(stage,r,manifest);SmrWorkflowRuntime.health(stage,r,runtime,manifest);Path qtlPrefix=inputs.resolve("qtl");
                    if(r.qtl().get("kind").equals("qfile")){Path home=Files.createDirectory(worker.resolve("prepare"));qtlPrefix=home.resolve("original");var options=new ArrayList<>(List.of("--qfile",inputs.resolve("qtl.qfile").toString(),"--make-besd"));if(r.qtl().get("storage").equals("dense"))options.add("--make-besd-dense");finish(options,qtlPrefix,r);require(SmrWorkflowRuntime.execute(stage,home,"QTL-preparation",options,r,runtime,manifest)==0,"Original QTL preparation failed; inspect original logs");}
                    var qtl=SmrWorkflowBesd.read(qtlPrefix,r,budget);if(r.qtl().get("kind").equals("qfile")){int differences=SmrWorkflowInputs.preparation(supplied,qtl,worker.resolve("native-preparation-ledger.tsv"),budget);if(differences>0)warnings.add("LEGACY DERIVED-SE PRECISION: "+differences+" original1.3.1 SE values differ by exactly1 binary32 ULP from the independent Java inverse-CDF expectation. Both values and each discrepancy remain in worker/native-preparation-ledger.tsv; the original stored SE is used unchanged. This explicit preparation-audit precision limit does not apply to supplied-SE branches or beta values. Larger discrepancies fail; no native replacement or byte-identical inverse-CDF claim occurs.");}var qtlPins=new LinkedHashMap<Path,NextflowFiles.Pin>();for(String suffix:List.of(".besd",".epi",".esi")){Path p=Path.of(qtlPrefix+suffix);qtlPins.put(p,NextflowFiles.pin(p,r.inputBytes(),()->{}));}var population=SmrWorkflowInputs.population(inputs,qtl,gwas,r,budget);try(var ledger=Files.newBufferedWriter(worker.resolve("native-sample-order.tsv"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){ledger.write("FID\tIID\n");for(String sample:population.samples())ledger.write(sample+"\n");}
                    Path cases=Files.createDirectory(worker.resolve("cases"));var reports=new ArrayList<Map<String,Object>>();
                    for(var a:r.analyses()){Path home=Files.createDirectory(cases.resolve(text(a.get("id"))));var options=options(inputs,qtlPrefix,home.resolve("original"),a,r);require(SmrWorkflowRuntime.execute(stage,home,text(a.get("id")),options,r,runtime,manifest)==0,"Original SMR case failed: "+a.get("id")+"; inspect original logs");reports.add(SmrWorkflowAudit.analysis(home,a,population,r,budget,warnings));for(Captured c:captures)c.verify();for(var e:qtlPins.entrySet())verify(e.getKey(),e.getValue());verify(request,requestPin);runtime.verify();}
                    for(Path home:List.of(worker.resolve("health"),worker.resolve("prepare"),cases))if(Files.exists(home))diagnostics(home,warnings,r);SmrWorkflowRuntime.finalCapacity(worker,r);for(Captured c:captures)c.verify();for(var e:qtlPins.entrySet())verify(e.getKey(),e.getValue());verify(request,requestPin);runtime.verify();var provenance=new LinkedHashMap<String,Object>();provenance.put("profile",SmrWorkflowRequest.PROFILE);provenance.put("version",r.version());provenance.put("request_sha256",requestPin.sha256());provenance.put("captured_inputs",pins);provenance.put("original_source_commit",manifest.get("original_source_commit"));provenance.put("exact_runtime_files",manifest.get("exact_runtime_files"));provenance.put("analyses",reports);provenance.put("native_operations",budget.used);provenance.put("reference_sample_count",population.samples().size());provenance.put("historical_paper_binary_or_causal_calibration_inferred",false);NextflowFiles.writeJson(stage.resolve("provenance.json"),provenance);Path results=Files.createDirectory(stage.resolve("results"));for(var a:r.analyses()){Path home=cases.resolve(text(a.get("id"))),target=Files.createDirectory(results.resolve(text(a.get("id"))));for(String suffix:List.of(".smr",".msmr",".snps4msmr.list",".prbregion4msmr.list")){Path file=home.resolve("original"+suffix);if(Files.exists(file))Files.copy(file,target.resolve(file.getFileName()));}Files.copy(home.resolve("native-audit.json"),target.resolve("native-audit.json"));}state.put("status","PASS_ORIGINAL_SMR_HEIDI_WORKFLOW");state.put("result_admitted",true);state.put("analyses",reports.size());
                }catch(SmrWorkflowRuntime.Unavailable failure){exit[0]=3;state.put("status","SKIP3_DEPENDENCY_UNAVAILABLE");state.put("cause",failure.toString());warnings.add("SKIP3 DEPENDENT ANALYSIS SKIPPED: "+failure);quarantine(stage);}
                catch(Exception failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause",failure.toString());warnings.add("FAIL2: "+failure);quarantine(stage);}
                catch(OutOfMemoryError failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; retry NEW paths with permitted heap/capacity without omitting variants/probes.");quarantine(stage);}
                if(exit[0]!=0&&Files.isDirectory(stage.resolve("worker")))try{diagnostics(stage.resolve("worker"),warnings,r);}catch(IOException logFailure){warnings.add("ORIGINAL LOG EXTRACTION LIMIT: "+logFailure+"; complete original log bytes remain in worker/.");}state.put("required_action",ACTION);NextflowFiles.writeJson(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);manifest.put("result_admitted",state.get("result_admitted"));manifest.put("scope",SCOPE);
            });emit(exit[0]==0?output:error,(exit[0]==0?"Original SMR/HEIDI workflow admitted: ":exit[0]==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO RESULT ADMITTED: ")+r.out());emit(error,"WARNINGS / REQUIRED ACTIONS: "+r.out().resolve("WARNINGS.md")+"\n"+ACTION);return exit[0];
        }catch(Exception failure){emit(error,"FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    static List<String> options(Path inputs,Path qtl,Path prefix,Map<String,Object> a,SmrWorkflowRequest.Request r)throws IOException {
        boolean multi=a.get("kind").equals("multi");var h=object(a.get("heidi"));String method=text(h.get("method"));var result=new ArrayList<>(List.of("--gwas-summary",inputs.resolve("gwas.ma").toString(),"--beqtl-summary",qtl.toString(),"--peqtl-smr",numeric(a,"qtl_p"),"--cis-wind",numeric(a,"window_kb")));if(r.reference().get("kind").equals("plink-bed"))Collections.addAll(result,"--bfile",inputs.resolve("reference").toString());if(multi||!method.equals("off"))Collections.addAll(result,"--maf",numeric(a,"minimum_maf"));
        if(r.probes().get("kind").equals("supplied"))Collections.addAll(result,"--extract-probe",inputs.resolve("probes.list").toString());
        if(method.equals("off"))result.add("--heidi-off");else{Collections.addAll(result,"--heidi-mtd",method.equals("original")?"0":"1","--peqtl-heidi",numeric(h,"qtl_p"),"--ld-upper-limit",numeric(h,"ld_upper"),"--heidi-min-m",numeric(h,"minimum_snps"),r.version().equals("1.3.1")?"--psmr":"--heidi-skip-thresh",numeric(h,"skip_smr_p"));if(method.equals("top20")){Collections.addAll(result,"--ld-lower-limit",numeric(h,"ld_lower"),"--heidi-max-m",numeric(h,"maximum_snps"));if(r.version().equals("1.4.3"))Collections.addAll(result,"--max_num_ld",numeric(h,"maximum_ld_candidates"));}}
        var f=object(a.get("frequency_check"));if(f.get("kind").equals("disabled"))result.add("--disable-freq-ck");else Collections.addAll(result,"--diff-freq",numeric(f,"maximum_difference"),"--diff-freq-prop",numeric(f,"maximum_excluded_fraction"));var overlap=object(a.get("sample_overlap"));if(overlap.get("kind").equals("estimate-original"))Collections.addAll(result,"--sample-overlap","--pmecs",numeric(overlap,"null_p"),"--mmecs",numeric(overlap,"minimum_null_snps"));else if(overlap.get("kind").equals("source-flag-without-estimation"))result.add("--sample-overlap");if(multi){var m=object(a.get("multi"));Collections.addAll(result,"--smr-multi","--set-wind",numeric(m,"window_kb"),"--ld-multi-snp",numeric(m,"ld_r2"));}finish(result,prefix,r);return result;
    }
    private static String numeric(Map<String,Object> m,String key)throws IOException {Object n=m.get(key);require(n instanceof NextflowParameters.NumberToken||n instanceof Number,"Missing numeric option: "+key);return n instanceof NextflowParameters.NumberToken token?token.text():n.toString();}
    private static void finish(List<String> options,Path out,SmrWorkflowRequest.Request r){Collections.addAll(options,"--out",out.toString(),"--thread-num",Integer.toString(r.threads()));}
    private static Captured capture(Path original,Path copy,long remaining)throws IOException {require(remaining>=0,"Combined input capacity exceeded");var pin=NextflowFiles.pin(original,remaining,()->{});try(var in=Files.newInputStream(original,LinkOption.NOFOLLOW_LINKS);var out=Files.newOutputStream(copy,StandardOpenOption.CREATE_NEW)){byte[] buffer=new byte[65536];long count=0;for(int n=in.read(buffer);n>=0;n=in.read(buffer)){require(n<=remaining-count,"Input grew beyond capacity");out.write(buffer,0,n);count+=n;}require(count==pin.bytes(),"Input changed during capture");}var captured=new Captured(original,copy,pin);captured.verify();return captured;}
    private static void verify(Path path,NextflowFiles.Pin pin)throws IOException {require(pin.equals(NextflowFiles.pin(path,pin.bytes(),()->{})),"Input/request changed: "+path);}
    private static void diagnostics(Path root,List<String> warnings,SmrWorkflowRequest.Request r)throws IOException {try(var paths=Files.walk(root)){for(Path file:paths.filter(p->p.getFileName().toString().equals("stdout.log")||p.getFileName().toString().equals("stderr.log")).toList()){require(Files.size(file)<=r.tableBytes(),"Original log exceeds maximum_table_bytes");try(var lines=Files.lines(file,StandardCharsets.UTF_8)){for(String line:lines.filter(s->s.contains("WARNING")||s.contains("ERROR")||s.contains("Error:")).limit(1000).toList())warnings.add("ORIGINAL LOG ["+root.relativize(file)+"]: "+line);}}}}
    private static void quarantine(Path stage)throws IOException {Path results=stage.resolve("results");if(Files.exists(results))Files.move(results,stage.resolve("unadmitted-partial-results"));}
    /** Preserve the complete owned attempt even if final manifest generation or publication itself fails. */
    private static void transaction(Path destination,FollowupSupport.Job job)throws Exception {
        Path out=destination.toAbsolutePath().normalize();require(!Files.exists(out,LinkOption.NOFOLLOW_LINKS),"Output already exists");Files.createDirectories(out.getParent());Path stage=Files.createTempDirectory(out.getParent(),".smr-attempt-");var manifest=new LinkedHashMap<String,Object>();manifest.put("schema_version",1);manifest.put("operation","original-SMR-HEIDI-development");manifest.put("started_at",java.time.Instant.now().toString());
        try{job.execute(stage,manifest);var outputs=new TreeMap<String,Object>();try(var paths=Files.walk(stage)){for(Path file:paths.filter(Files::isRegularFile).toList()){var pin=NextflowFiles.pin(file,Long.MAX_VALUE,()->{});outputs.put(stage.relativize(file).toString().replace('\\','/'),Map.of("bytes",pin.bytes(),"sha256",pin.sha256()));}}manifest.put("outputs",outputs);manifest.put("completed_at",java.time.Instant.now().toString());NextflowFiles.writeJson(stage.resolve("manifest.json"),manifest);Files.move(stage,out);}
        catch(Exception failure){retainUnexpected(stage,failure);throw new IOException("No result admitted; complete owned attempt retained at "+stage,failure);}
        catch(Error failure){retainUnexpected(stage,failure);throw failure;}
    }
    private static void retainUnexpected(Path stage,Throwable failure){try{quarantine(stage);Files.writeString(stage.resolve("analysis-status.json"),NextflowJson.json(Map.of("status","FAIL2_ATTEMPT_OR_PUBLICATION_FAILED","result_admitted",false,"cause",failure.toString(),"required_action",ACTION))+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);Path warnings=stage.resolve("WARNINGS.md");String prior=Files.exists(warnings)?Files.readString(warnings):"";Files.writeString(warnings,"# FAIL2 NO RESULT ADMITTED\n\n"+failure+"\n\nCOMPLETE OWNED ATTEMPT RETAINED AT: "+stage+"\n\nREQUIRED ACTION: "+ACTION+"\n\n"+prior);}catch(Exception recording){failure.addSuppressed(recording);}}
    private static Path resolved(Path path)throws IOException {var missing=new ArrayDeque<Path>();Path current=path.toAbsolutePath().normalize();while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"No existing path ancestor");missing.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path name:missing)current=current.resolve(name);return current.normalize();}
    private static void emit(PrintStream stream,String value){byte[] raw=(value+"\n").getBytes(StandardCharsets.UTF_8);stream.write(raw,0,raw.length);stream.flush();}
}
